     and ta.teacher_id in (select tt.teacher_id from talk_teacher tt join sys_user su on tt.user_id = su.user_id where su.user_name = #{params.counselorUsername})
     and st.dept_id is not null and exists (select 1 from sys_dept d where (d.dept_id = #{params.secretaryDeptId} or find_in_set(#{params.secretaryDeptId}, d.ancestors)) and d.dept_id = st.dept_id)

order by ta.appointment_time desc

